    #[inductive(consume_end)]
    fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        let head = pre.consumer.get_Consuming_0();
        let len = pre.backing_cells.len();
        let next_head = Self::inc_wrap(head, len);

        // Prove not_overlapping
        assert(post.not_overlapping()) by {
            match pre.producer {
                ProducerState::Idle(_) => {
                    // post.producer = Idle, post.consumer = Idle => trivially holds
                }
                ProducerState::Producing(tail) => {
                    // From pre.not_overlapping: head != tail, inc_wrap(tail, len) != head
                    assert(head != tail);
                    assert(Self::inc_wrap(tail, len) != head);
                    // Need: inc_wrap(tail, len) != next_head = inc_wrap(head, len)
                    // Since head != tail, inc_wrap is injective on [0, len)
                    assert(Self::inc_wrap(tail, len) != next_head) by {
                        if tail + 1 == len {
                            assert(Self::inc_wrap(tail, len) == 0nat);
                            if head + 1 == len {
                                // both = len-1, but head != tail, contradiction
                                assert(tail == head);
                                assert(false);
                            } else {
                                assert(next_head == head + 1);
                                // head + 1 >= 1 > 0
                            }
                        } else {
                            assert(Self::inc_wrap(tail, len) == tail + 1);
                            if head + 1 == len {
                                assert(next_head == 0nat);
                                // tail + 1 >= 1 > 0
                            } else {
                                assert(next_head == head + 1);
                                // tail != head => tail + 1 != head + 1
                            }
                        }
                    };
                }
            }
        };

        // Prove in_bounds
        assert(post.in_bounds()) by {
            assert(0 <= next_head) by {};
            assert(next_head < len) by {
                if head + 1 == len {
                    assert(next_head == 0nat);
                } else {
                    assert(next_head == head + 1);
                }
            };
        };

        // Prove valid_storage_all
        // Key fact from not_overlapping: pre.tail != head
        assert(pre.tail != head) by {
            match pre.producer {
                ProducerState::Idle(tail) => {
                    // not_overlapping with Idle/Consuming: head != tail, and tail == pre.tail
                    // in_bounds: pre.tail == tail
                    assert(pre.tail == tail);
                }
                ProducerState::Producing(tail) => {
                    // in_bounds: pre.tail == tail
                    // not_overlapping with Producing/Consuming: head != tail
                    assert(pre.tail == tail);
                    assert(head != tail);
                }
            }
        };

        assert(post.valid_storage_all()) by {
            assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
                if i == head {
                    // post.is_checked_out(head) should be false:
                    // - post.consumer = Idle(next_head) != Consuming(head)
                    // - post.producer = pre.producer != Producing(head)
                    //   (since if pre.producer = Producing(tail), then tail != head from not_overlapping)
                    assert(!post.is_checked_out(i)) by {
                        assert(post.consumer != ConsumerState::Consuming(i));
                        match pre.producer {
                            ProducerState::Idle(_) => {
                                assert(post.producer != ProducerState::Producing(i));
                            }
                            ProducerState::Producing(tail) => {
                                assert(tail != head);
                                assert(post.producer == ProducerState::Producing(tail));
                                assert(post.producer != ProducerState::Producing(i));
                            }
                        }
                    };
                    // Storage has perm at head
                    assert(post.storage.dom().contains(i));
                    assert(post.storage.index(i) == perm);
                    assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
                    // head is NOT in the post active range (perm.is_uninit())
                    assert(!post.in_active_range(i)) by {
                        // post.head = next_head = inc_wrap(head, len)
                        // post.tail = pre.tail
                        // Show that head is not in [next_head, pre.tail) (circular)
                        if head + 1 == len {
                            // next_head = 0, head = len-1
                            // pre.tail != head = len-1, and pre.tail < len, so pre.tail <= len-2 < head
                            // so head > pre.tail: if post.head <= post.tail (0 <= pre.tail), range is [0, pre.tail)
                            // head = len-1 >= pre.tail, so head is NOT in [0, pre.tail)
                            assert(next_head == 0nat);
                            assert(post.head == 0nat);
                            assert(post.head <= post.tail);
                            // range: post.head <= head < post.tail, i.e., 0 <= len-1 < pre.tail
                            // but pre.tail <= len-2 = head-1 < head, so head >= post.tail
                            assert(head >= post.tail) by {
                                assert(pre.tail != head);
                                assert(pre.tail < len);
                                // pre.tail <= len-2 = head-1 < head
                            };
                        } else {
                            // next_head = head + 1 > head
                            assert(next_head == head + 1);
                            assert(post.head == head + 1);
                            // In active range: if post.head <= post.tail: need post.head <= head (false)
                            // If post.head > post.tail: need head >= post.head (false) || head < post.tail
                            //   but post.head = head+1 > post.tail means pre.tail < head+1
                            //   so pre.tail <= head, thus head < pre.tail = post.tail is false
                            if post.head <= post.tail {
                                // range: post.head <= head < post.tail, but post.head = head+1 > head
                                assert(post.head > i);
                            } else {
                                // range: head >= post.head || head < post.tail
                                // post.head = head+1 > head, so first fails
                                // post.tail < post.head = head+1, so post.tail <= head, so head < post.tail is false
                                assert(i < post.head);
                                assert(i >= post.tail);
                            }
                        }
                    };
                    // Conclude: uninit cell at head

